    "id": "vault-er-diagrams",
    "title": "ER Diagrams",
    "author": "Product Management & Systems Faculty",
    "year": "2026",
    "category": "Research Paper",
    "tags": [
      "Concept",
      "Core"
    ],
    "readTime": "4m",
