    "id": "vault-gcp",
    "title": "GCP",
    "author": "Product Management & Systems Faculty",
    "year": "2026",
    "category": "Research Paper",
    "tags": [
      "definition",
      "pm-implication"
    ],
    "readTime": "5m",
